    from collections import Counter

    # 统计每个数字的频率
    frequency = Counter(lst)

    # 找到满足条件的数字
    for num, freq in frequency.items():
        if num <= freq:
            return num

    # 如果没有找到符合条件的数字，返回 -1
    return -1

