def is_multiply_prime(a):
    if a < 2:
        return False
    prime_factors = []
    for i in range(2, int(a**0.5) + 1):
        while a % i == 0:
            prime_factors.append(i)
            a //= i
    if a > 1:
        prime_factors.append(a)
    return len(prime_factors) == 3

def hex_key(num):
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
