            count += 1
    return count

def decimal_to_binary(decimal):
    """Converts a decimal number to its binary representation as a string."""
    if decimal == 0:
        return "db0db"

    binary_str = ""
    while decimal > 0:
        binary_str = str(decimal % 2) + binary_str
        decimal //= 2

    return "db" + binary_str + "db"

