def file_name_check(file_name):
    # Check if the file name contains more than three digits
    if sum(c.isdigit() for c in file_name) > 3:
        return 'No'

    # Check if the file name contains exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split the file name into two parts: before and after the dot
    parts = file_name.split('.')

    # Check if the substring before the dot is empty or starts with a non-letter
    if not parts[0] or not parts[0][0].isalpha():
        return 'No'

    # Check if the substring after the dot is one of the allowed extensions
    if parts[1] not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'

