def maxAverageOfPath(matrix):
    n = len(matrix)
    dp = [[0] * n for _ in range(n)]

    # Initialize the first row and first column
    for i in range(n):
        dp[0][i] = matrix[0][i]
        dp[i][0] = matrix[i][0]

    # Fill the dp table
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = matrix[i][j] + max(dp[i-1][j], dp[i][j-1])

    # Calculate the maximum average
    max_avg = 0
    for i in range(n):
        for j in range(n):
            max_avg = max(max_avg, dp[i][j] / (i + j + 1))

    return max_avg

