import heapq

def merge_sorted_list(num1, num2, num3):
    # 使用 heapq 将列表转换为最小堆
    heap = []
    for num in num1:
        heapq.heappush(heap, num)
    for num in num2:
        heapq.heappush(heap, num)
    for num in num3:
        heapq.heappush(heap, num)

    # 使用 heapq 排序最小堆
    sorted_list = []
    while heap:
        sorted_list.append(heapq.heappop(heap))

    return sorted_list

