def lps(str1):
    n = len(str1)
    dp = [[0] * n for _ in range(n)]

    # Initialize the diagonal elements
    for i in range(n):
        dp[i][i] = 1

    # Fill the dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if str1[i] == str1[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

