def set_left_most_unset_bit(n):
    if n == 0:
        return 1
    if not n & n + 1:
        return n
    pos, temp, count = (0, n, 1)
    while temp:
        if not temp & 1:
            pos = count
        count += 1
        temp >>= 1
    return n | 1 << pos

